        // Arrange
        val instance = MainActivity()

        // Act & Assert - Verifying no java.lang.NullPointerException is thrown when null states occur
        try {
            instance.onCreate()
            assertTrue("Method executed safely without raising runtime exception", true)
        } catch (e: NullPointerException) {
            fail("Regression test failed: java.lang.NullPointerException was thrown: " + e.message)
        }
    }
